<template>
  <section ref="readingRoot" @mouseup="captureReadingSelection" @keyup="captureReadingSelection" class="library-document" :class="{'folder-document':item.kind==='folder'}" @keydown.ctrl.s.prevent="save" @keydown.meta.s.prevent="save">
    <div class="document-toolbar">
      <div class="document-context"><slot name="navigation"></slot><span class="document-status"><i :class="editing?'fa-solid fa-pen':'fa-regular fa-file-lines'"></i>{{editing?'正在编辑':doc?.format==='link'?'云端原件':typeLabel}}<span v-if="saving" class="unsaved">保存中…</span><span v-else-if="dirty" class="unsaved">待保存</span><span v-else-if="saved" class="saved">已自动保存</span></span></div>
      <div class="document-actions"><button v-if="canEdit&&!editing" class="edit-button" @click="startEditing"><i class="fa-solid fa-pen"></i>直接编辑</button><template v-if="editing"><button class="edit-button" :disabled="saving" @click="save"><i class="fa-solid fa-check"></i>{{saving?'保存中…':'完成编辑'}}</button></template><button v-if="!readonly" @click="showVersions"><i class="fa-solid fa-clock-rotate-left"></i>历史版本</button><button v-if="!readonly" @click="showProjects"><i class="fa-solid fa-link"></i>关联项目</button><button v-if="doc?.format!=='link'" @click="action('export')"><i class="fa-solid fa-download"></i>{{doc?.format==='html'?'导出 Word':'下载原件'}}</button><button v-if="doc?.format!=='link'" @click="action('open')"><i class="fa-solid fa-arrow-up-right-from-square"></i>打开原件</button><button v-if="item.sourceUrl" @click="openSource"><i class="fa-solid fa-arrow-up-right-from-square"></i>极库云原件</button><slot name="view-actions"></slot></div>
    </div>
    <p v-if="doc?.previewNotice" class="preview-notice">{{doc.previewNotice}}</p>
    <p v-if="error" class="document-error" role="alert">{{error}} <button v-if="conflict" @click="reloadOriginal">读取最新原件</button></p>
    <div v-if="versionsOpen" class="document-extra"><header><strong>历史版本</strong><button @click="versionsOpen=false">关闭</button></header><p v-if="!versions.length">此文档还没有历史版本</p><div v-for="version in versions" :key="version.id"><span>{{new Date(version.createdAt).toLocaleString('zh-CN')}} · {{version.label}}</span><button :disabled="saving" @click="restoreVersion(version)">恢复此版</button></div></div>
    <div v-if="projectsOpen" class="document-extra"><header><strong>关联项目 · 使用同一份原件</strong><button @click="projectsOpen=false">关闭</button></header><label v-for="project in projects" :key="project.slug"><input type="checkbox" v-model="projectSlugs" :value="project.slug"> {{project.name}}</label><p v-if="!projects.length">先创建项目，再关联资料</p><button class="edit-button" @click="saveProjects">保存关联</button></div>
    <div v-if="loading" class="document-placeholder">正在读取文档…</div>
    <template v-else-if="doc">
      <div v-if="editing&&doc.format==='html'" class="format-toolbar"><label>字号<UiSelect field v-model.number="fontSize" aria-label="文字字号" @pointerdown="rememberSelection" @focus="rememberSelection" @change="applySize" :options="[...(sizes).map((size) => ({ value: size, label: String(size) + ' pt' }))]" /></label><button title="加粗" @mousedown.prevent="format('bold')"><i class="fa-solid fa-bold"></i></button><button title="斜体" @mousedown.prevent="format('italic')"><i class="fa-solid fa-italic"></i></button><button title="下划线" @mousedown.prevent="format('underline')"><i class="fa-solid fa-underline"></i></button><button @mousedown.prevent="format('formatBlock','h2')">标题</button><button @mousedown.prevent="format('formatBlock','p')">正文</button><button title="项目列表" @mousedown.prevent="format('insertUnorderedList')"><i class="fa-solid fa-list-ul"></i></button><button title="编号列表" @mousedown.prevent="format('insertOrderedList')"><i class="fa-solid fa-list-ol"></i></button><span>{{formatNotice || '正文和表格可直接修改 · 自动保存'}}</span></div>
      <div v-if="doc.format==='spreadsheet'" class="sheet-preview">
        <div class="sheet-tabs"><button v-for="(sheet,index) in doc.sheets" :key="index" :class="{active:sheetIndex===index}" @click="sheetIndex=index;rowPage=0">{{sheet.name}}</button></div>
        <div class="sheet-grid"><table v-if="activeSheet?.rows.length"><thead><tr><th>#</th><th v-for="column in sheetColumns" :key="column">{{columnName(column)}}</th></tr></thead><tbody><tr v-for="row in pageRows" :key="row.number"><th>{{row.number}}</th><td v-for="column in sheetColumns" :key="column" :title="cell(row,column)?.formula? '公式：'+cell(row,column).formula : String(cell(row,column)?.value||'')">{{cell(row,column)?.value ?? ''}}</td></tr></tbody></table><p v-else>此工作表暂无内容</p></div>
        <div class="sheet-pager"><span>{{activeSheet?.rows.length||0}} 行 · {{sheetColumns.length}} 列</span><button :disabled="rowPage===0" @click="rowPage--">上一页</button><span>{{rowPage+1}} / {{Math.max(1,Math.ceil((activeSheet?.rows.length||0)/200))}}</span><button :disabled="(rowPage+1)*200>=(activeSheet?.rows.length||0)" @click="rowPage++">下一页</button></div>
      </div>
      <div v-else-if="doc.format==='slides'" class="slides-preview"><section v-for="slide in doc.slides" :key="slide.number" class="slide-page"><span class="slide-number">{{slide.number}} / {{doc.slides.length}}</span><h2>{{slide.paragraphs[0]||'幻灯片 '+slide.number}}</h2><p v-for="(paragraph,index) in slide.paragraphs.slice(1)" :key="index">{{paragraph}}</p><div class="slide-images"><img v-for="(source,index) in slide.images" :key="index" :src="source" :alt="'幻灯片 '+slide.number+' 图片 '+(index+1)" loading="lazy" /></div></section></div>
      <div v-else-if="doc.format==='archive'" class="archive-preview"><p>压缩包包含 {{doc.files.length}} 个文件和文件夹</p><div v-for="(file,index) in doc.files" :key="index"><i :class="file.directory?'fa-solid fa-folder-open':'fa-regular fa-file'"></i><span>{{file.name}}</span><small>{{file.directory?'文件夹':formatSize(file.size)}}</small></div></div>
      <iframe v-else-if="doc.format==='web'" :srcdoc="doc.content" title="HTML 文件预览" sandbox="" class="pdf-preview"></iframe>
      <div v-else-if="doc.format==='html'" class="document-scroll" @click="followLink"><article v-if="editing" ref="editor" class="document-paper" contenteditable="true" role="textbox" aria-label="编辑资料正文" aria-multiline="true" spellcheck="false" v-html="initialContent" @input="changed" @mouseup="rememberSelection" @keyup="rememberSelection"></article><article v-else class="document-paper" v-html="safeContent"></article><slot name="related-files" :editing="editing"></slot></div>
      <textarea v-else-if="doc.format==='text'&&editing" v-model="text" class="text-editor" aria-label="编辑文本正文" @input="changed"></textarea>
      <pre v-else-if="doc.format==='text'" class="text-preview">{{doc.content}}</pre>
      <div v-else-if="doc.format==='link'" class="link-preview"><div><i class="fa-solid fa-link"></i><h2>{{item.title}}</h2><p>{{item.sourceUrl?'此文件保留极库云的在线原件，可以查看和编辑。':'已保存的网页链接'}}</p><p class="source-link">{{doc.content}}</p><button class="edit-button" @click="action('open')">打开云端文档 <i class="fa-solid fa-arrow-up-right-from-square"></i></button><small>可以下载原件后上传到当前文件夹，作为本地资料直接编辑。</small></div></div>
      <iframe v-else-if="doc.previewType==='pdf'||doc.ext==='pdf'" :src="doc.url" title="PDF 文档预览" class="pdf-preview"></iframe>
      <div v-else-if="doc.previewType==='image'" class="media-preview"><img :src="doc.url" :alt="item.title" /></div>
      <div v-else-if="doc.previewType==='video'" class="media-preview"><video :src="doc.url" controls preload="metadata" @error="mediaError=true" /><p v-if="mediaError" class="media-error">当前视频编码无法直接播放，请使用「打开原件」。</p></div>
      <div v-else-if="doc.previewType==='audio'" class="media-preview"><audio :src="doc.url" controls preload="metadata" @error="mediaError=true" /><p v-if="mediaError" class="media-error">当前音频编码无法直接播放，请使用「打开原件」。</p></div>
      <div v-else class="link-preview"><div><i class="fa-regular fa-file"></i><h2>{{item.title}}</h2><p>{{doc.ext?.toUpperCase()}} 文件 · {{formatSize(item.size)}}</p><button class="edit-button" @click="action('open')">用本机程序打开</button><button @click="action('export')">下载文件</button><small>Excel、PowerPoint 和其他附件可使用对应软件编辑。</small></div></div>
    </template>
  </section>
</template>
<script setup>
import {ref,computed,nextTick,onMounted,onBeforeUnmount} from 'vue';
const props=defineProps({item:{type:Object,required:true},autoEdit:{type:Boolean,default:false},readonly:Boolean,api:Object}),emit=defineEmits(['saved','selection']);
const readingRoot=ref(null);
function captureReadingSelection(event){
  if(editing.value||!event.target.closest('.document-paper,.text-preview,.sheet-grid,.slides-preview'))return;
  const selection=window.getSelection();
  if(!selection?.rangeCount)return;
  const range=selection.getRangeAt(0);
  if(!readingRoot.value?.contains(range.startContainer)||!readingRoot.value?.contains(range.endContainer))return;
  emit('selection',{text:selection.toString().trim()});
}
const doc=ref(null),loading=ref(true),error=ref(''),editing=ref(false),saving=ref(false),saved=ref(false),dirty=ref(false),editor=ref(null),initialContent=ref(''),text=ref(''),fontSize=ref(12),formatNotice=ref(''),sheetIndex=ref(0),rowPage=ref(0),mediaError=ref(false);
const sizes=[8,9,10,10.5,11,12,14,16,18,20,22,24,28,32,36,48,72];let selection=null;
const service=props.api||window.api.library;
const conflict=ref(false),versionsOpen=ref(false),versions=ref([]),projectsOpen=ref(false),projects=ref([]),projectSlugs=ref([]);
const draftKey='fde-library-draft:'+props.item.id;
let autosaveTimer=null,savePromise=null,revision=0,disposed=false,lastDraftContent=null;
function currentContent(){return doc.value?.format==='html'?(editor.value?.innerHTML ?? lastDraftContent ?? initialContent.value):text.value;}
function keepDraft(){lastDraftContent=currentContent();try{localStorage.setItem(draftKey,JSON.stringify({content:lastDraftContent,token:doc.value?.token}));}catch(_){} }
function scheduleSave(){clearTimeout(autosaveTimer);if(!disposed)autosaveTimer=setTimeout(()=>{autosaveTimer=null;void persist();},650);}
function clean(content){const document=new DOMParser().parseFromString(content||'','text/html');document.querySelectorAll('script,style,iframe,object,embed,form,input,button,link,meta').forEach(n=>n.remove());document.querySelectorAll('*').forEach(n=>Array.from(n.attributes).forEach(a=>{if(a.name.startsWith('on')||['contenteditable','autofocus'].includes(a.name)||(['href','src'].includes(a.name)&&/^\s*(javascript|vbscript):/i.test(a.value)))n.removeAttribute(a.name);}));return document.body.innerHTML;}
const activeSheet=computed(()=>doc.value?.sheets?.[sheetIndex.value]);
function columnIndex(cell){if(cell.index!==undefined)return cell.index;let index=0;for(const letter of (cell.ref||'A').match(/^[A-Z]+/i)?.[0]?.toUpperCase()||'A')index=index*26+letter.charCodeAt(0)-64;return index-1;}
function columnName(index){let name='';for(index++;index>0;index=Math.floor((index-1)/26))name=String.fromCharCode(65+(index-1)%26)+name;return name;}
const sheetColumns=computed(()=>[...new Set((activeSheet.value?.rows||[]).flatMap(row=>row.cells.map(columnIndex)))].sort((a,b)=>a-b));
const pageRows=computed(()=>(activeSheet.value?.rows||[]).slice(rowPage.value*200,(rowPage.value+1)*200).map(row=>({...row,byColumn:new Map(row.cells.map(cell=>[columnIndex(cell),cell]))})));
function cell(row,column){return row.byColumn.get(column);}
const safeContent=computed(()=>clean(doc.value?.content)),canEdit=computed(()=>!props.readonly&&['html','text'].includes(doc.value?.format)),typeLabel=computed(()=>props.item.kind==='folder'?'文件夹文档':doc.value?.format==='html'?(doc.value.ext==='md'?'Markdown 文档':'Word 文档'):doc.value?.format==='spreadsheet'?'表格预览':doc.value?.previewType==='pdf'&&doc.value?.ext!=='pdf'?'文档页式预览':doc.value?.ext?.toUpperCase()||'资料');
async function load(){try{const result=await service.read(props.item.id);if(!result.success)throw Error(result.error);doc.value=result.document;const stored=props.readonly?null:localStorage.getItem(draftKey);if(stored!==null){let draft;try{draft=JSON.parse(stored);}catch{draft={content:stored};}if(typeof draft?.content!=='string')draft={content:stored};editing.value=true;lastDraftContent=draft.content;dirty.value=true;initialContent.value=clean(draft.content);text.value=draft.content;if(draft.token!==doc.value.token){conflict.value=true;error.value='恢复草稿与原件版本不同。请复制需要保留的文字，再读取最新原件合并。';}}else if(props.autoEdit&&canEdit.value){startEditing();}}catch(e){error.value=e.message;}finally{loading.value=false;}if(dirty.value&&!conflict.value){await nextTick();changed();}}
async function reloadOriginal(){if(dirty.value&&!window.confirm('当前草稿会另存为本机恢复草稿，随后读取最新原件。继续吗？'))return;try{if(dirty.value)localStorage.setItem(draftKey+':recovery:'+Date.now(),currentContent());const result=await service.read(props.item.id);if(!result.success)throw Error(result.error);doc.value=result.document;localStorage.removeItem(draftKey);dirty.value=false;editing.value=false;conflict.value=false;error.value='';}catch(e){error.value=e.message;}}
async function showVersions(){if(!await save({finishEditing:false}))return;const result=await service.history(props.item.id);if(!result.success){error.value=result.error;return;}versions.value=result.versions;versionsOpen.value=true;}
async function restoreVersion(version){if(!window.confirm('恢复所选版本？当前版本会保留在历史中。'))return;if(!await save({finishEditing:false}))return;const result=await service.restoreRevision(props.item.id,version.id,doc.value.token);if(!result.success){error.value=result.error;return;}versionsOpen.value=false;dirty.value=false;editing.value=false;await load();emit('saved');}
async function showProjects(){projects.value=await window.api.hermes.listProjects({kind:'project'});const result=await window.api.library.list();projectSlugs.value=result.entries?.find(e=>e.id===props.item.id)?.projectSlugs||[];projectsOpen.value=true;}
async function saveProjects(){const result=await service.associate(props.item.id,projectSlugs.value);if(!result.success){error.value=result.error;return;}projectsOpen.value=false;emit('saved');}
function startEditing(){initialContent.value=safeContent.value;text.value=doc.value.content;editing.value=true;selection=null;formatNotice.value='';}
function changed(){revision++;dirty.value=true;saved.value=false;rememberSelection();keepDraft();scheduleSave();}
function rememberSelection(){const s=window.getSelection();if(!s?.rangeCount||!editor.value)return;const r=s.getRangeAt(0);if(editor.value.contains(r.startContainer)&&editor.value.contains(r.endContainer))selection=r.cloneRange();}
function format(command,value=null){editor.value?.focus();document.execCommand(command,false,value);changed();}
function applySize(){if(!selection||selection.collapsed||!editor.value?.contains(selection.commonAncestorContainer)){formatNotice.value='请先选中需要调整的文字。';return;}editor.value.focus();const s=window.getSelection();s.removeAllRanges();s.addRange(selection);document.execCommand('styleWithCSS',false,false);document.execCommand('fontSize',false,'7');editor.value.querySelectorAll('font[size="7"]').forEach(n=>{n.removeAttribute('size');n.style.fontSize=fontSize.value+'pt';});formatNotice.value='';changed();}
// Write one snapshot at a time. Edits made while it is saving remain dirty.
function persist(){
  if(conflict.value)return Promise.resolve(false);
  if(savePromise)return savePromise;
  if(!editing.value||!dirty.value)return Promise.resolve(true);
  const snapshotRevision=revision,content=doc.value.format==='html'?clean(currentContent()):text.value;
  saving.value=true;error.value='';
  savePromise=(async()=>{
    let succeeded=false;
    try{
      const result=await service.write(props.item.id,doc.value.format,content,doc.value.token);
      if(!result.success)throw Error(result.error);
      doc.value.content=content;doc.value.token=result.entry.token;
      if(snapshotRevision===revision){dirty.value=false;saved.value=true;localStorage.removeItem(draftKey);}
      emit('saved');succeeded=true;return true;
    }catch(e){error.value='自动保存失败：'+e.message;if(e.message.includes('原件'))conflict.value=true;keepDraft();return false;}
    finally{saving.value=false;savePromise=null;if(succeeded&&dirty.value)scheduleSave();}
  })();
  return savePromise;
}
async function save({finishEditing=true}={}){
  clearTimeout(autosaveTimer);
  while(dirty.value||savePromise){if(!await persist())return false;clearTimeout(autosaveTimer);}
  if(finishEditing)editing.value=false;
  return true;
}
async function beforeLeave(){return save({finishEditing:false});}
async function action(name){if(!await save({finishEditing:false}))return;error.value='';try{const result=await service[name](props.item.id);if(result.canceled)return;if(!result.success)throw Error(result.error);}catch(e){error.value=e.message;}}
async function checkExternal(){if(props.readonly||dirty.value||saving.value||loading.value)return;try{const result=await service.read(props.item.id);if(result.success&&result.document.token!==doc.value?.token){doc.value=result.document;editing.value=false;}}catch(e){error.value=e.message;}}
function openSource(){if(/^https?:\/\//.test(props.item.sourceUrl||''))window.api.shell.openExternal(props.item.sourceUrl);}
function followLink(event){if(editing.value)return;const a=event.target.closest('a');if(a){event.preventDefault();if(/^https?:\/\//.test(a.href))window.api.shell.openExternal(a.href);}}
function formatSize(value){return value?(value>1024*1024?(value/1024/1024).toFixed(1)+' MB':Math.ceil(value/1024)+' KB'):'已保存在本机';}
function flushOnExit(){
  clearTimeout(autosaveTimer);
  if(dirty.value){keepDraft();void save({finishEditing:false});}
}
onMounted(()=>{load();window.addEventListener('beforeunload',flushOnExit);window.addEventListener('focus',checkExternal);});
onBeforeUnmount(()=>{disposed=true;flushOnExit();window.removeEventListener('beforeunload',flushOnExit);window.removeEventListener('focus',checkExternal);});
defineExpose({beforeLeave,save});
</script>
<style scoped>
